pm.test('Embarcador 1 continua', () => {
    if (pm.response.code === 200) {
        const jsonData = pm.response.json();
        pm.expect(Array.isArray(jsonData)).to.be.true;
        pm.expect(jsonData.some(e => e.id === 1)).to.be.true;
    } else {
        pm.expect(pm.response.json()).to.have.property('erro');
    }
});
